<?php
if(!defined('ABSPATH'))exit;
function legacyx_register_intelligence_actions(){register_post_type('legacyx_intel_action',array('labels'=>array('name'=>'Intelligence Actions','singular_name'=>'Intelligence Action','menu_name'=>'Action Center','add_new_item'=>'Add Intelligence Action','edit_item'=>'Edit Intelligence Action'),'public'=>false,'show_ui'=>true,'show_in_menu'=>'legacyx-firm-os','supports'=>array('title'),'capability_type'=>'post','map_meta_cap'=>true,'show_in_rest'=>false));}
add_action('init','legacyx_register_intelligence_actions');
function legacyx_intelligence_action_box(){add_meta_box('legacyx_intel_action_details','Management Action','legacyx_render_intelligence_action_box','legacyx_intel_action','normal','high');}
add_action('add_meta_boxes','legacyx_intelligence_action_box');
function legacyx_render_intelligence_action_box($post){wp_nonce_field('legacyx_save_intel_action','legacyx_intel_action_nonce');$client=(int)get_post_meta($post->ID,'_legacyx_client_profile_id',true);$status=get_post_meta($post->ID,'_legacyx_action_status',true)?:'Open';$priority=get_post_meta($post->ID,'_legacyx_action_priority',true)?:'Normal';$due=get_post_meta($post->ID,'_legacyx_action_due_date',true);$owner=get_post_meta($post->ID,'_legacyx_action_owner',true);$source=get_post_meta($post->ID,'_legacyx_action_source',true);$note=get_post_meta($post->ID,'_legacyx_action_note',true);$clients=get_posts(array('post_type'=>'legacyx_client','post_status'=>'any','numberposts'=>-1,'orderby'=>'title','order'=>'ASC'));echo '<p><label><strong>Client Relationship</strong></label><br><select name="legacyx_action_client" style="width:100%"><option value="">Firm-level action</option>';foreach($clients as $c)echo '<option value="'.esc_attr($c->ID).'" '.selected($client,$c->ID,false).'>'.esc_html($c->post_title).'</option>';echo '</select></p><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:14px"><p><label><strong>Status</strong></label><br><select name="legacyx_action_status" style="width:100%">';foreach(array('Open','In Progress','Waiting','Completed','Dismissed') as $o)echo '<option '.selected($status,$o,false).'>'.esc_html($o).'</option>';echo '</select></p><p><label><strong>Priority</strong></label><br><select name="legacyx_action_priority" style="width:100%">';foreach(array('Normal','High','Critical') as $o)echo '<option '.selected($priority,$o,false).'>'.esc_html($o).'</option>';echo '</select></p><p><label><strong>Due Date</strong></label><br><input type="date" name="legacyx_action_due_date" value="'.esc_attr($due).'" style="width:100%"></p><p><label><strong>Owner / Responsible Staff</strong></label><br><input type="text" name="legacyx_action_owner" value="'.esc_attr($owner).'" style="width:100%"></p></div><p><label><strong>Intelligence Source</strong></label><br><input type="text" name="legacyx_action_source" value="'.esc_attr($source).'" placeholder="Executive briefing, Client Intelligence, Watchlist…" style="width:100%"></p><p><label><strong>Management Note / Expected Next Step</strong></label><br><textarea name="legacyx_action_note" style="width:100%;min-height:110px">'.esc_textarea($note).'</textarea></p>';}
function legacyx_save_intelligence_action($id){if(get_post_type($id)!=='legacyx_intel_action'||!isset($_POST['legacyx_intel_action_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_intel_action_nonce'])),'legacyx_save_intel_action')||!current_user_can('edit_post',$id))return;$map=array('client_profile_id'=>absint($_POST['legacyx_action_client']??0),'action_status'=>sanitize_text_field(wp_unslash($_POST['legacyx_action_status']??'Open')),'action_priority'=>sanitize_text_field(wp_unslash($_POST['legacyx_action_priority']??'Normal')),'action_due_date'=>sanitize_text_field(wp_unslash($_POST['legacyx_action_due_date']??'')),'action_owner'=>sanitize_text_field(wp_unslash($_POST['legacyx_action_owner']??'')),'action_source'=>sanitize_text_field(wp_unslash($_POST['legacyx_action_source']??'')),'action_note'=>sanitize_textarea_field(wp_unslash($_POST['legacyx_action_note']??'')));foreach($map as $k=>$v)update_post_meta($id,'_legacyx_'.$k,$v);}
add_action('save_post_legacyx_intel_action','legacyx_save_intelligence_action');
function legacyx_intelligence_action_rows($limit=8){return get_posts(array('post_type'=>'legacyx_intel_action','post_status'=>'any','numberposts'=>$limit,'meta_query'=>array(array('key'=>'_legacyx_action_status','value'=>array('Completed','Dismissed'),'compare'=>'NOT IN')),'orderby'=>'modified','order'=>'DESC'));}
function legacyx_render_intelligence_action_center(){if(!current_user_can('legacyx_view_reports'))return;$rows=legacyx_intelligence_action_rows();$new=admin_url('post-new.php?post_type=legacyx_intel_action');?>
<section class="lxi-actions"><div class="lxi-actions-head"><div><span>INTELLIGENCE ACTION CENTER</span><h2>Turn Insight Into Execution</h2><p>Convert management findings into owned, dated and trackable actions without changing the underlying intelligence records.</p></div><a href="<?php echo esc_url($new);?>">+ New Management Action</a></div><?php if(!$rows):?><div class="lxi-actions-empty"><strong>No open intelligence actions.</strong><p>Create an action when an intelligence finding requires management follow-through.</p></div><?php else:?><div class="lxi-actions-table"><div class="lxi-action-row head"><span>Action</span><span>Relationship</span><span>Priority</span><span>Status</span><span>Due</span><span></span></div><?php foreach($rows as $r):$cid=(int)get_post_meta($r->ID,'_legacyx_client_profile_id',true);$client=$cid?get_the_title($cid):'Firm-level';$priority=get_post_meta($r->ID,'_legacyx_action_priority',true)?:'Normal';$status=get_post_meta($r->ID,'_legacyx_action_status',true)?:'Open';$due=get_post_meta($r->ID,'_legacyx_action_due_date',true);?><div class="lxi-action-row"><span><strong><?php echo esc_html(get_the_title($r));?></strong><small><?php echo esc_html(get_post_meta($r->ID,'_legacyx_action_source',true)?:'Management');?></small></span><span><?php echo esc_html($client);?></span><span><?php echo esc_html($priority);?></span><span><?php echo esc_html($status);?></span><span><?php echo esc_html($due?:'—');?></span><span><a href="<?php echo esc_url(get_edit_post_link($r->ID));?>">Open →</a></span></div><?php endforeach;?></div><?php endif;?><small class="lxi-actions-boundary">Actions are internal management workflow records. Creating an action does not alter client intelligence scores or imply an external outcome.</small></section><?php }
function legacyx_intelligence_actions_inject(){if(!current_user_can('legacyx_view_reports'))return;$screen=get_current_screen();if(!$screen||$screen->id!=='toplevel_page_legacyx-firm-os')return;ob_start();legacyx_render_intelligence_action_center();$html=ob_get_clean();if(!$html)return;?><div id="legacyx-actions-source" style="display:none"><?php echo $html;?></div><script>document.addEventListener('DOMContentLoaded',function(){var src=document.getElementById('legacyx-actions-source'),brief=document.querySelector('.lxi-brief');if(src&&brief){var w=document.createElement('div');w.innerHTML=src.innerHTML;brief.insertAdjacentElement('afterend',w.firstElementChild);src.remove();}});</script><?php }
add_action('admin_footer','legacyx_intelligence_actions_inject',10);
function legacyx_intelligence_actions_styles($hook){if($hook!=='toplevel_page_legacyx-firm-os')return;wp_register_style('legacyx-intelligence-actions',false);wp_enqueue_style('legacyx-intelligence-actions');$css='.lxi-actions{background:#fff;border:1px solid #ded8ce;padding:28px;margin-top:18px}.lxi-actions-head{display:flex;justify-content:space-between;gap:24px;align-items:end}.lxi-actions-head span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.lxi-actions-head h2{font:29px Georgia,serif;margin:5px 0 8px}.lxi-actions-head p{color:#746e65;margin:0;max-width:760px}.lxi-actions-head>a{background:#171512;color:#fff;padding:12px 16px;text-decoration:none;font-weight:800}.lxi-actions-table{margin-top:22px}.lxi-action-row{display:grid;grid-template-columns:2fr 1.2fr .7fr .8fr .7fr .5fr;gap:12px;align-items:center;padding:14px 10px;border-bottom:1px solid #ece7df}.lxi-action-row.head{font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;background:#f7f4ed}.lxi-action-row small{display:block;color:#746e65;margin-top:4px}.lxi-action-row a{color:#171512;font-weight:800;text-decoration:none}.lxi-actions-empty{background:#f7f4ed;padding:20px;margin-top:20px}.lxi-actions-empty p{color:#746e65;margin-bottom:0}.lxi-actions-boundary{display:block;color:#817a71;margin-top:16px}@media(max-width:800px){.lxi-actions-head{display:block}.lxi-actions-head>a{display:inline-block;margin-top:16px}.lxi-action-row{grid-template-columns:1fr 1fr}.lxi-action-row.head{display:none}.lxi-action-row>span:first-child,.lxi-action-row>span:last-child{grid-column:1/-1}}';wp_add_inline_style('legacyx-intelligence-actions',$css);}add_action('admin_enqueue_scripts','legacyx_intelligence_actions_styles');
